:root {
  --bg: #0b1220;
  --bg-2: #0f1a2e;
  --panel: #13203a;
  --panel-2: #18294a;
  --border: #24375c;
  --text: #e6eefc;
  --text-dim: #8ea3c4;
  --text-mute: #5f7396;
  --cyan: #38bdf8;
  --blue: #3b82f6;
  --green: #22c55e;
  --amber: #f59e0b;
  --orange: #f97316;
  --red: #ef4444;
  --violet: #a78bfa;
  --shadow: 0 8px 28px rgba(0, 0, 0, 0.35);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body, #root { height: 100%; }

body {
  font-family: 'PingFang SC', 'Microsoft YaHei', 'Segoe UI', system-ui, -apple-system, sans-serif;
  background:
    radial-gradient(1200px 600px at 80% -10%, rgba(56, 189, 248, 0.08), transparent 60%),
    radial-gradient(900px 500px at -10% 110%, rgba(59, 130, 246, 0.1), transparent 60%),
    var(--bg);
  color: var(--text);
  font-size: 14px;
  line-height: 1.5;
}

button {
  font-family: inherit;
  font-size: 13px;
  cursor: pointer;
  border: 1px solid var(--border);
  background: var(--panel-2);
  color: var(--text);
  padding: 6px 14px;
  border-radius: 7px;
  transition: all 0.15s ease;
  white-space: nowrap;
}
button:hover:not(:disabled) { border-color: var(--cyan); color: var(--cyan); }
button:disabled { opacity: 0.4; cursor: not-allowed; }

.btn-primary { background: linear-gradient(135deg, #0ea5e9, #2563eb); border-color: transparent; color: #fff; }
.btn-primary:hover:not(:disabled) { color: #fff; filter: brightness(1.12); }
.btn-danger { background: rgba(239, 68, 68, 0.14); border-color: rgba(239, 68, 68, 0.5); color: #fca5a5; }
.btn-danger:hover:not(:disabled) { background: rgba(239, 68, 68, 0.25); color: #fff; }
.btn-ghost { background: transparent; }
.btn-sm { padding: 4px 10px; font-size: 12px; border-radius: 6px; }

/* ---------- 顶部导航 ---------- */
.app-header {
  display: flex;
  align-items: center;
  gap: 22px;
  padding: 0 24px;
  height: 60px;
  background: rgba(15, 26, 46, 0.85);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 40;
}
.logo { display: flex; align-items: center; gap: 10px; font-size: 17px; font-weight: 700; }
.logo .snow { font-size: 22px; filter: drop-shadow(0 0 6px rgba(56, 189, 248, 0.6)); }
.logo small { font-weight: 400; color: var(--text-mute); font-size: 11px; margin-left: 4px; }

.nav { display: flex; gap: 4px; }
.nav button {
  background: transparent;
  border: none;
  color: var(--text-dim);
  padding: 8px 16px;
  font-size: 14px;
  position: relative;
}
.nav button:hover { color: var(--text); }
.nav button.active { color: #fff; font-weight: 600; }
.nav button.active::after {
  content: '';
  position: absolute;
  left: 16px; right: 16px; bottom: -2px;
  height: 2px;
  background: linear-gradient(90deg, var(--cyan), var(--blue));
  border-radius: 2px;
}
.nav .badge-count {
  display: inline-block;
  min-width: 18px;
  padding: 0 5px;
  margin-left: 5px;
  border-radius: 9px;
  font-size: 11px;
  line-height: 18px;
  text-align: center;
  background: var(--red);
  color: #fff;
}
.header-right { margin-left: auto; display: flex; align-items: center; gap: 16px; }
.conn { display: flex; align-items: center; gap: 7px; font-size: 12px; color: var(--text-dim); }
.dot { width: 8px; height: 8px; border-radius: 50%; background: var(--green); box-shadow: 0 0 8px var(--green); }
.dot.off { background: var(--red); box-shadow: 0 0 8px var(--red); }
.clock { font-variant-numeric: tabular-nums; color: var(--text-dim); font-size: 13px; }

/* ---------- 布局 ---------- */
.app-main { padding: 22px 24px 48px; max-width: 1560px; margin: 0 auto; }

.page-title { display: flex; align-items: center; justify-content: space-between; margin-bottom: 18px; }
.page-title h2 { font-size: 19px; font-weight: 700; }
.page-title .sub { color: var(--text-mute); font-size: 12px; margin-top: 2px; }

/* ---------- 统计卡 ---------- */
