  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow);
}
.modal-head { display: flex; align-items: center; gap: 12px; padding: 18px 22px; border-bottom: 1px solid var(--border); }
.modal-head h3 { font-size: 17px; }
.modal-head .x { margin-left: auto; }
.modal-body { padding: 20px 22px; overflow-y: auto; }
.modal-foot { padding: 14px 22px; border-top: 1px solid var(--border); display: flex; justify-content: flex-end; gap: 10px; }

.detail-meta { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-bottom: 18px; }
.detail-meta .cell { background: var(--bg-2); border: 1px solid var(--border); border-radius: 10px; padding: 10px 13px; }
.detail-meta .cell .l { font-size: 11px; color: var(--text-mute); }
.detail-meta .cell .v { font-size: 16px; font-weight: 600; margin-top: 3px; }

/* ---------- Toast ---------- */
.toast-stack { position: fixed; right: 20px; bottom: 20px; z-index: 100; display: flex; flex-direction: column; gap: 10px; width: min(380px, calc(100vw - 40px)); }
.toast {
  display: flex; gap: 10px; align-items: flex-start;
  padding: 12px 14px;
  border-radius: 10px;
  background: var(--panel-2);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
  animation: slide-in 0.25s ease;
  font-size: 13px;
}
.toast .tic { font-size: 15px; line-height: 1.4; }
.toast.error { border-color: rgba(239, 68, 68, 0.6); background: rgba(60, 20, 25, 0.95); }
.toast.warning { border-color: rgba(245, 158, 11, 0.55); }
.toast.success { border-color: rgba(34, 197, 94, 0.5); }
.toast.info { border-color: rgba(56, 189, 248, 0.45); }
.toast .close { margin-left: auto; cursor: pointer; color: var(--text-mute); }
@keyframes slide-in { from { transform: translateX(30px); opacity: 0; } to { transform: none; opacity: 1; } }

/* ---------- 下拉菜单 ---------- */
.dropdown { position: relative; display: inline-block; }
.dropdown-menu {
  position: absolute; right: 0; top: calc(100% + 6px);
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 6px;
  min-width: 190px;
  z-index: 50;
  box-shadow: var(--shadow);
}
.dropdown-menu button { display: block; width: 100%; text-align: left; background: transparent; border: none; padding: 8px 10px; border-radius: 6px; }
.dropdown-menu button:hover { background: rgba(56, 189, 248, 0.1); color: var(--cyan); }
.dropdown-menu .dd-sep { height: 1px; background: var(--border); margin: 5px 4px; }
.dropdown-menu .dd-title { padding: 5px 10px 3px; font-size: 11px; color: var(--text-mute); }

.legend { display: flex; gap: 16px; font-size: 12px; color: var(--text-dim); flex-wrap: wrap; }
.legend i { display: inline-block; width: 16px; height: 3px; border-radius: 2px; vertical-align: middle; margin-right: 5px; }

@media (max-width: 1100px) {
  .stats-row { grid-template-columns: repeat(3, 1fr); }
  .kanban { grid-template-columns: repeat(2, 1fr); }
  .detail-meta { grid-template-columns: repeat(2, 1fr); }
}

